import numpy as np
import math

def feature(current, candidates, tour, start):
    """Angle at the current city between the incoming arrival direction and the outgoing leg to each candidate, as a normalized cosine (straight-through = +1)."""
    if tour.shape[0] < 2:
        return np.zeros(len(candidates))
    prev = tour[-2]
    cur = tour[-1]
    in_vec = cur - prev
    n_in = math.hypot(in_vec[0], in_vec[1])
    if n_in < 1e-12:
        return np.zeros(len(candidates))
    in_unit = in_vec / n_in
    out_vec = candidates - cur
    n_out = np.hypot(out_vec[:, 0], out_vec[:, 1])
    n_out = np.where(n_out < 1e-12, 1e-12, n_out)
    out_unit = out_vec / n_out[:, None]
    cos = out_unit @ in_unit
    return np.clip(cos, -1.0, 1.0)

import numpy as np

def feature(current, candidates, tour, start):
    """Cosine alignment of the outgoing leg with the incoming leg, gated to the first half of the decisions."""
    k = candidates.shape[0]
    m = tour.shape[0]
    if k <= 1 or m < 2:
        return np.zeros(k)
    frac = m / (m + k - 1)
    gate = max(0.0, 1.0 - 2.0 * frac)
    if gate == 0.0:
        return np.zeros(k)
    incoming = current - tour[-2]
    norm_in = np.linalg.norm(incoming)
    if norm_in < 1e-12:
        return np.zeros(k)
    u = incoming / norm_in
    outgoing = candidates - current
    norm_out = np.linalg.norm(outgoing, axis=1)
    cos = (outgoing @ u) / np.maximum(norm_out, 1e-9)
    return gate * cos
